-- Fictional local owner/reviewers only. The outer transaction rolls everything back.
reset role;
insert into auth.users values('10000000-0000-4000-8000-000000000004');
insert into public.platform_admin_roles values('10000000-0000-4000-8000-000000000003','owner');
set local role service_role;
do $$ declare owner_id uuid:='10000000-0000-4000-8000-000000000003'; reviewer uuid:='10000000-0000-4000-8000-000000000004'; learner uuid:='10000000-0000-4000-8000-000000000001'; admin_id uuid:='10000000-0000-4000-8000-000000000002'; req uuid:=gen_random_uuid(); result jsonb; again jsonb; review_id uuid; old_hash text; personal uuid; cp uuid; begin
 perform pg_temp.expect_error(format('select public.assessment_manage_reviewer(%L,%L,''roofing'',''Spanish'',''English'',''domain'',true,0,''Fixture only'',%L)',admin_id,reviewer,gen_random_uuid()),'Registered platform owner access required');
 perform pg_temp.expect_error(format('select public.assessment_manage_reviewer(%L,%L,''roofing'',''Spanish'',''English'',''response'',true,0,''Fixture only'',%L)',owner_id,owner_id,gen_random_uuid()),'cannot grant themselves');
 result:=public.assessment_manage_reviewer(owner_id,reviewer,'roofing','Spanish','English','curriculum',true,0,'Local fixture qualification confirmed',req);
 again:=public.assessment_manage_reviewer(owner_id,reviewer,'roofing','Spanish','English','curriculum',true,0,'Local fixture qualification confirmed',req);
 if result<>again or (select count(*) from public.assessment_reviewer_admin_events where request_id=req)<>1 then raise exception 'Reviewer grant retry duplicated'; end if;
 if exists(select 1 from public.assessment_reviewers where user_id=reviewer) then raise exception 'Content grant exposed learner review'; end if;
 perform pg_temp.expect_error(format('select public.assessment_manage_reviewer(%L,%L,''roofing'',''Spanish'',''English'',''curriculum'',false,1,''Changed payload'',%L)',owner_id,reviewer,req),'request key reused');
 perform pg_temp.expect_error(format('select public.assessment_manage_reviewer(%L,%L,''roofing'',''Spanish'',''English'',''curriculum'',false,0,''Stale fixture'',%L)',owner_id,reviewer,gen_random_uuid()),'scope conflict');
 old_hash:=public.assessment_content_review_context(reviewer,'test-entrance')->>'fingerprint';
 if length(old_hash)<>64 then raise exception 'Content fingerprint missing'; end if;
 perform pg_temp.expect_error(format('select public.assessment_content_review_context(%L,''test-entrance'')',admin_id),'Assigned content reviewer access required');
 req:=gen_random_uuid();
 review_id:=public.assessment_record_content_review(reviewer,'test-entrance','curriculum','changes_requested',old_hash,'Fixture review: question wording requires revision',req);
 if public.assessment_record_content_review(reviewer,'test-entrance','curriculum','changes_requested',old_hash,'Fixture review: question wording requires revision',req)<>review_id then raise exception 'Content review retry duplicated'; end if;
 perform pg_temp.expect_error(format('select public.assessment_record_content_review(%L,''test-entrance'',''domain'',''approved'',%L,''Not assigned'',%L)',reviewer,old_hash,gen_random_uuid()),'Assigned content reviewer access required');
 perform pg_temp.expect_error(format('select public.assessment_record_content_review(%L,''test-entrance'',''curriculum'',''approved'',%L,''Changed payload'',%L)',reviewer,old_hash,req),'request key reused');
 perform public.assessment_note_content_exposure(reviewer,'test-entrance');
 perform public.assessment_note_content_exposure(reviewer,'test-entrance');
 if (select count(*) from public.assessment_content_exposures where user_id=reviewer)<>1 then raise exception 'Duplicate private exposure'; end if;
 personal:=public.assessment_create_enrollment(reviewer,reviewer,null,'roofing-es-en-test','2026-10-15','UTC',gen_random_uuid());
 select id into cp from public.assessment_checkpoints where enrollment_id=personal and checkpoint='entrance';
 perform pg_temp.expect_error(format('select public.assessment_start_attempt(%L,%L,''test-entrance'',%L,false)',reviewer,cp,gen_random_uuid()),'independent assessment bank is required');
 -- Changing either the item source or its lesson manifest invalidates the old review fingerprint.
 update public.assessment_forms set rubric_version='revised-fixture' where id='test-entrance';
 perform pg_temp.expect_error(format('select public.assessment_record_content_review(%L,''test-entrance'',''curriculum'',''approved'',%L,''Stale form'',%L)',reviewer,old_hash,gen_random_uuid()),'Content conflict');
 if public.assessment_content_review_context(reviewer,'test-entrance')->>'fingerprint'=old_hash then raise exception 'Changed rubric reused content fingerprint'; end if;
 old_hash:=public.assessment_content_review_context(reviewer,'test-entrance')->>'fingerprint';
 update public.assessment_releases set lesson_manifest='{"reviewed":false,"fixtureRevision":2}' where id='roofing-es-en-test';
 if public.assessment_content_review_context(reviewer,'test-entrance')->>'fingerprint'=old_hash then raise exception 'Changed lessons reused content fingerprint'; end if;
 perform public.assessment_manage_reviewer(owner_id,reviewer,'roofing','Spanish','English','curriculum',false,1,'Local fixture revoke',gen_random_uuid());
 perform pg_temp.expect_error(format('select public.assessment_content_review_context(%L,''test-entrance'')',reviewer),'Assigned content reviewer access required');
 perform pg_temp.expect_error(format('select public.assessment_record_content_review(%L,''test-entrance'',''curriculum'',''approved'',%L,''Revoked reviewer'',%L)',reviewer,old_hash,gen_random_uuid()),'Assigned content reviewer access required');
 if not exists(select 1 from public.assessment_content_decisions where id=review_id) then raise exception 'Revocation erased review history'; end if;
 perform public.assessment_manage_reviewer(owner_id,reviewer,'roofing','Spanish','English','response',true,0,'Local response reviewer fixture',gen_random_uuid());
 perform pg_temp.expect_error(format('select public.assessment_content_review_context(%L,''test-entrance'')',reviewer),'Assigned content reviewer access required');
 perform public.assessment_manage_reviewer(owner_id,reviewer,'roofing','Spanish','English','response',false,1,'Local response revoke fixture',gen_random_uuid());
 if (select active from public.assessment_reviewers where user_id=reviewer) then raise exception 'Response reviewer revocation failed'; end if;
 if exists(select 1 from public.assessment_forms where id='test-entrance' and (status<>'draft' or calibrated)) then raise exception 'Content review published a draft'; end if;
 if exists(select 1 from public.assessment_content_reviewers where user_id=reviewer and target_language<>'Spanish') then raise exception 'Grant leaked into another language'; end if;
 personal:=public.assessment_create_enrollment(owner_id,owner_id,null,'roofing-es-en-test','2026-10-15','UTC',gen_random_uuid());
 select id into cp from public.assessment_checkpoints where enrollment_id=personal and checkpoint='entrance';
 insert into public.assessment_attempts(checkpoint_id,attempt_number,form_id,form_snapshot,start_request_id) values(cp,1,'test-entrance','{"pilot":false,"definition":{"items":[]}}',gen_random_uuid());
 perform pg_temp.expect_error(format('select public.assessment_note_content_exposure(%L,''test-entrance'')',owner_id),'Finish your official assessment');
 if exists(select 1 from public.assessment_content_exposures where user_id=owner_id) then raise exception 'Denied content read still recorded an exposure'; end if;
 perform pg_temp.expect_error(format('update public.assessment_content_decisions set note=''Changed'' where id=%L',review_id),'permission denied');
 perform pg_temp.expect_error('delete from public.assessment_reviewer_admin_events','permission denied');
 perform pg_temp.expect_error('truncate public.assessment_content_decisions','permission denied');
end $$;
